export const MOTION_PAINTERS = Object.fromEntries(Object.entries(MOTION_PRESETS).map(([id, p]) => [p.effect || id, p.paint]));
export const MOTION_PRESET_IDS = Object.keys(MOTION_PRESETS);
export function motionPresetMeta(id) {
  const p = MOTION_PRESETS[id];
  return p ? { label: p.label, hand: !!p.hand } : null;
}
